async function unlockManagerResources(){
  const matriculeInput = document.getElementById("managerMatricule");
  const input = document.getElementById("managerPin");
  const error = document.getElementById("managerPinError");
  const gate = document.getElementById("managerGate");
  const button = document.getElementById("managerPinSubmit");

  if(!input || !error || !gate) return;

  const now = Date.now();

  if(now < managerLockedUntil){
    const secondsLeft = Math.ceil((managerLockedUntil - now) / 1000);
    error.textContent = `Trop de tentatives. Réessayez dans ${secondsLeft}s.`;
    error.classList.add("active");
    return;
  }

  // --- Vérification du matricule, avant même de tenter le code ---
  const matricule = matriculeInput ? matriculeInput.value.trim() : "";
  const manager = findManagerByMatricule(matricule);

  if(!manager){
    error.textContent = "Matricule non reconnu.";
    error.classList.add("active");
    return;
  }
  // --- Fin vérification matricule ---

  const pin = input.value.trim();

  if(!/^\d{4}$/.test(pin)){
    error.textContent = "Saisissez un code composé de 4 chiffres.";
    error.classList.add("active");
    return;
  }

  if(button) button.disabled = true;

  const resources = await decryptResources(pin);

  if(resources){
    managerFailedAttempts = 0;
    error.classList.remove("active");
    gate.hidden = true;

    // --- On retient qui est connecté, et on l'affiche ---
    currentManager = manager;
    sessionStorage.setItem("managerName", manager.name);
    showManagerWelcome(manager.name);
    // --- Fin identification ---

    renderResources(resources);
    initManagerSearch();
    initAnnuaireSearches(resources);
    initContactsSearches(resources);
  }else{
    managerFailedAttempts += 1;

    if(managerFailedAttempts >= MANAGER_MAX_ATTEMPTS){
      managerLockedUntil = Date.now() + MANAGER_LOCKOUT_MS;
      managerFailedAttempts = 0;
      error.textContent = `Trop de tentatives. Réessayez dans ${Math.ceil(MANAGER_LOCKOUT_MS / 1000)}s.`;
    }else{
      error.textContent = "Code incorrect.";
    }

    error.classList.add("active");
    input.select();

    if(button) button.disabled = false;
  }
}

document.addEventListener("DOMContentLoaded", () => {
  const input = document.getElementById("managerPin");
  if(!input) return;

  insertMatriculeField();

  input.focus();

  input.addEventListener("input", () => {
    input.value = input.value.replace(/\D/g, "").slice(0, 4);
    const error = document.getElementById("managerPinError");
    if(error) error.classList.remove("active");
  });

  input.addEventListener("keydown", event => {
    if(event.key === "Enter"){
      event.preventDefault();
      unlockManagerResources();
    }
  });

  document.getElementById("managerPinSubmit")
    ?.addEventListener("click", unlockManagerResources);
});

/* =========================================================
   POP-UP MOBILE AVANT OUVERTURE D'UN DOCUMENT INTRANET
   (même logique et mêmes classes CSS que dans app.js)
========================================================= */
function isMobileDevice(){
  return window.matchMedia("(max-width:600px)").matches;
}

function showMobileDocumentNotice(url, title){
  const existing = document.getElementById("documentModal");
  if(existing) existing.remove();

  const modal = document.createElement("div");
  modal.id = "documentModal";

  modal.innerHTML = `
    <div class="document-overlay" onclick="closeDocumentModal(event)">
      <div class="document-modal" role="dialog" aria-modal="true"
           aria-labelledby="documentModalTitle" onclick="event.stopPropagation()">

        <button class="document-close" type="button" aria-label="Fermer"
                onclick="closeDocumentModal()">✕</button>

        <div class="document-icon">📄</div>

        <h3 id="documentModalTitle">${escapeHtml(title || "Document RH")}</h3>

        <p>
          Vous consultez ce document depuis un téléphone.
          L'accès à certains documents ou pages de l'intranet peut nécessiter une reconnexion.
        </p>

        <p class="document-info">
          Si l'intranet vous demande vos identifiants, connectez-vous puis
          revenez dans votre navigateur.
        </p>

        <p class="document-info">
          Après avoir consulté le lien, balayez votre écran vers la gauche pour revenir
          à votre assistant RH.
        </p>

        <div class="actions document-actions">
          <a class="action primary" href="${escapeHtml(url)}">🔐 Ouvrir le document</a>
          <button class="action" type="button" onclick="closeDocumentModal()">Retour</button>
        </div>

      </div>
    </div>
  `;

  document.body.appendChild(modal);
}

function closeDocumentModal(event){
  if(event && event.target !== event.currentTarget) return;
  const modal = document.getElementById("documentModal");
  if(modal) modal.remove();
}

document.addEventListener("click", event => {
  const link = event.target.closest("[data-resource-link]");
  if(!link) return;
  if(!isMobileDevice()) return;

  event.preventDefault();
  showMobileDocumentNotice(link.getAttribute("href"), link.dataset.title || link.textContent.trim());
});
